import numpy as np
from PIL import Image
D=np.load('/app/output/retry_left_depth.npy').astype(float);I=np.array(Image.open('/app/output/retry_left_depth.png'))
T=np.array([[.7326154777847623,.13381387467676192,-.6673592800390178,-.775],[-.6806427563048065,.1440316742115515,-.718317697898091,-.856],[0,.9804839232582088,.1965992783104522,1.209],[0,0,0,1]])
def wp(u,v):
 z=D[v,u]; c=np.array([(u-160)*z/386.274,-(v-160)*z/386.274,-z,1]); return z,(T@c)[:3],I[v,u]
for v in range(145,181,3):
 for u in range(140,181,5):
  z,p,rgb=wp(u,v)
  if z<2: print((u,v),round(z,3),np.round(p,3),rgb)
# fruit center projection
Tw=np.linalg.inv(T)
for p in [[.272,.28,.79,1],[.2683,.2686,.818,1]]:
 c=Tw@p;cv=np.array([c[0],-c[1],-c[2]]); print('uv',p[:3],386.274*cv[:2]/cv[2]+[160,160])
PY

